  "No se encontró la carpeta de extensiones.": ["Couldn't find the extensions folder.", "Não foi possível encontrar a pasta de extensões."],
  "La galería respondió algo que no entiendo.": ["The gallery answered something I don't understand.", "A galeria respondeu algo que eu não entendo."],
  "No pude leer ese script.": ["I couldn't read that script.", "Não consegui ler esse script."],
  "Ese archivo no es de la galería.": ["That file isn't from the gallery.", "Esse arquivo não é da galeria."],
