let lang: Lang = "es";

export const locale = () => ({ es: "es", en: "en", pt: "pt-BR" })[lang];

export const weekLetters = () => ({ es: "LMXJVSD", en: "MTWTFSS", pt: "STQQSSD" })[lang];

export function tr(text: string): string {
  if (lang === "es") return text;
  const core = text.trim();
  if (!core) return text;
  const index = lang === "en" ? 0 : 1;
  const exact = EXACT[core];
  if (exact) return text.replace(core, exact[index]);
  for (const [pattern, en, pt] of PATTERNS) {
    if (pattern.test(core)) return text.replace(core, core.replace(pattern, index === 0 ? en : pt));
  }
  return text;
}

const written = new WeakMap<Node, string>();
const shown = new WeakMap<Node, string>();
const ATTRIBUTES = ["placeholder", "aria-label", "title"];
const attributes = new WeakMap<Element, Record<string, string>>();
let watcher: MutationObserver | null = null;

function translateText(node: Text) {
  const now = node.data;
  const source = shown.get(node) === now ? (written.get(node) ?? now) : now;
  written.set(node, source);
  const target = tr(source);
  shown.set(node, target);
  if (target !== now) node.data = target;
}

function translateElement(element: Element) {
  for (const name of ATTRIBUTES) {
    const now = element.getAttribute(name);
    if (now === null) continue;
    const known = attributes.get(element) ?? {};
    const source = known[`shown:${name}`] === now ? (known[name] ?? now) : now;
    const target = tr(source);
    attributes.set(element, { ...known, [name]: source, [`shown:${name}`]: target });
    if (target !== now) element.setAttribute(name, target);
  }
}

function translateTree(root: Node) {
  if (root.nodeType === Node.TEXT_NODE) return translateText(root as Text);
  if (root.nodeType !== Node.ELEMENT_NODE) return;
  translateElement(root as Element);
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT);
  for (let node = walker.nextNode(); node; node = walker.nextNode()) {
    if (node.nodeType === Node.TEXT_NODE) translateText(node as Text);
    else translateElement(node as Element);
  }
}

export function setLanguage(next: Lang) {
  if (next === lang && (watcher || next === "es")) return;
  const hadOther = lang !== "es";
  lang = next;
  document.documentElement.lang = locale();
  if (lang === "es") {
    if (hadOther) translateTree(document.body);
    watcher?.disconnect();
    watcher = null;
    return;
  }
  translateTree(document.body);
  if (watcher) return;
  watcher = new MutationObserver((changes) => {
    for (const change of changes) {
      if (change.type === "characterData") translateText(change.target as Text);
      else if (change.type === "attributes") translateElement(change.target as Element);
      else for (const node of change.addedNodes) translateTree(node);
    }
  });
  watcher.observe(document.body, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ATTRIBUTES });
}
